From 6facb2e66f44b0259f9a6254e36c8178f18d70b1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 00:00:22 +0100
Subject: [PATCH] applets/systemtray: keep the settings of disabled tray
 widgets

Disabling a widget in the System Tray settings deleted its config group,
so enabling it again created a fresh applet with default settings. Keep
the config group and its id instead, so the widget comes back as it was.

BUG: 452599
---
 applets/systemtray/systemtray.cpp | 5 +----
 1 file changed, 1 insertion(+), 4 deletions(-)

diff --git a/applets/systemtray/systemtray.cpp b/applets/systemtray/systemtray.cpp
index 4c1db7a2e7..4e3e9001c4 100644
--- a/applets/systemtray/systemtray.cpp
+++ b/applets/systemtray/systemtray.cpp
@@ -425,11 +425,8 @@ void SystemTray::onEnabledAppletsChanged()
         } else {
             const QString task = applet->pluginMetaData().pluginId();
             if (!m_settings->isEnabledPlugin(task)) {
-                // in those cases we do delete the applet config completely
-                // as they were explicitly disabled by the user
-                applet->config().parent().deleteGroup();
+                // keep the applet config, so it is restored if the user enables it again
                 delete applet;
-                m_configGroupIds.remove(task);
             }
         }
     }
